import {readFileSync} from 'node:fs';
import {parseEnv} from 'node:util';
const projectRef='gkffvigcnsesbaihycay';
const key=parseEnv(readFileSync('.env.local','utf8')).SUPABASE_SERVICE_ROLE;
const claims=JSON.parse(Buffer.from(key.split('.')[1],'base64url').toString());
if(claims.role!=='service_role'||claims.ref!==projectRef)throw Error('scope');
const source=readFileSync('scripts/observe-comparator-strict-capacity.mjs','utf8');
const acceptedNames=new RegExp(source.match(/const acceptedNames = \/(.+)\/;/)[1]);
const acceptedLabels=new Set(['cpu','mode','device','datname','database','state','fstype','mountpoint']);
let bytes=0;let reader;const observed_at=new Date().toISOString();const started=performance.now();
try{
 const response=await fetch('https://gkffvigcnsesbaihycay.supabase.co/customer/v1/privileged/metrics',{headers:{Authorization:'Basic '+Buffer.from('service_role:'+key).toString('base64')},signal:AbortSignal.timeout(10000),redirect:'error'});
 reader=response.body?.getReader();if(!reader)throw Error('body');const chunks=[];
 while(true){const {value,done}=await reader.read();if(done)break;bytes+=value.byteLength;if(bytes>1048576)throw Error('budget');chunks.push(Buffer.from(value));}
 if(!response.ok)throw Error('http_'+response.status);
 const metrics=[];
 for(const line of Buffer.concat(chunks).toString('utf8').split('\n')){
  const match=line.match(/^([a-zA-Z_:][a-zA-Z0-9_:]*)(\{.*\})?\s+([-+0-9.eE]+)(?:\s+\d+)?$/);
  if(!match||!acceptedNames.test(match[1]))continue;
  const labels={};for(const label of (match[2]??'').matchAll(/([a-zA-Z_][a-zA-Z0-9_]*)="((?:\\.|[^"\\])*)"/g))if(acceptedLabels.has(label[1]))labels[label[1]]=JSON.parse('"'+label[2]+'"');
  const value=Number(match[3]);if(!Number.isFinite(value))throw Error('metric');metrics.push({name:match[1],labels,value});
 }
 for(const name of ['node_cpu_seconds_total','node_memory_MemAvailable_bytes','node_memory_MemTotal_bytes','pg_up','pg_exporter_last_scrape_error','max_connections_connection_count','connection_stats_connection_count'])if(!metrics.some(m=>m.name===name))throw Error('missing');
 const sum=name=>metrics.filter(m=>m.name===name).reduce((s,m)=>s+m.value,0);
 console.log(JSON.stringify({type:'sample',projectRef,observed_at,elapsed_ms:performance.now()-started,bytes,metrics,guard:{available_memory_percent:100*sum('node_memory_MemAvailable_bytes')/sum('node_memory_MemTotal_bytes'),connection_percent:100*sum('connection_stats_connection_count')/sum('max_connections_connection_count'),postgres_up:sum('pg_up')===1&&sum('pg_exporter_last_scrape_error')===0}}));
}catch(error){await reader?.cancel().catch(()=>{});console.log(JSON.stringify({type:'failure',projectRef,observed_at,bytes,error:/^(body|budget|http_\d{3}|metric|missing)$/.test(error.message)?error.message:error.name}));process.exitCode=1;}

